INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000003d',1,'APPROVED','PUBLISHED',
'{"objectives":["Make polite requests","Use könnte and würde","Distinguish requests from commands"],"explanation":{"intro":"Making requests politely is a key social skill. German uses Konjunktiv II forms for extra politeness.","culturalNote":"Germans value directness but also politeness. Könnten Sie...? is the gold standard polite request in shops and offices."},"examples":[{"german":"Könnten Sie mir helfen?","english":"Could you help me?"},{"german":"Würden Sie bitte leiser sein?","english":"Would you please be quieter?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can make polite requests in German."}}',
'{"items":[{"word":"könnten","translation":"could (polite)","pronunciation":"KÖN-ten","example":"Könnten Sie helfen?"},{"word":"würden","translation":"would","pronunciation":"VÜR-den","example":"Würden Sie warten?"},{"word":"bitte","translation":"please","pronunciation":"BIT-teh","example":"Bitte helfen Sie mir."},{"word":"die Bitte","translation":"request","pronunciation":"dee BIT-teh","example":"Eine Bitte hätte ich."},{"word":"gern","translation":"gladly","pronunciation":"GERN","example":"Ja, gern!"},{"word":"natürlich","translation":"of course","pronunciation":"nah-TÜR-likh","example":"Natürlich!"}]}',
'{"title":"Konjunktiv II for polite requests","pattern":"Könnten Sie / Würden Sie + infinitive?","explanation":"Könnten (could) and würden (would) are Konjunktiv II forms used for polite requests. They are much softer than können Sie or wollen Sie. Könnten Sie mir sagen...? = Could you tell me...?","examples":[{"sentence":"Könnten Sie das wiederholen?","translation":"Could you repeat that?"},{"sentence":"Würden Sie bitte unterschreiben?","translation":"Would you please sign?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Könnten Sie'' is used for?","options":["polite requests","commands","questions","statements"],"correctAnswer":"polite requests"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Could you help me?","options":["Könnten Sie mir helfen?","Helfen Sie mir!","Können Sie helfen?","Ich brauche Hilfe."],"correctAnswer":"Könnten Sie mir helfen?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ Sie bitte warten?","options":["Würden","Werden","Wären","Wollen"],"correctAnswer":"Würden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Of course, gladly!","wordBankItems":["Natürlich",",","gern","!"],"correctAnswer":"Natürlich , gern !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Natürlich'' means?","options":["of course","perhaps","probably","never"],"correctAnswer":"of course"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000003e',1,'APPROVED','PUBLISHED',
'{"objectives":["Give and follow complex directions","Use landmarks","Describe distance"],"explanation":{"intro":"Advanced direction-giving uses landmarks and distance expressions. Build on basic left/right/straight vocabulary.","culturalNote":"German cities are well-signed. Look for Stadtplan (city map) boards at major junctions. Apps like Google Maps work well but knowing German directions helps."},"examples":[{"german":"Gehen Sie an der Kirche vorbei.","english":"Go past the church."},{"german":"Es ist ungefähr 500 Meter entfernt.","english":"It is about 500 metres away."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can give and follow more detailed directions."}}',
'{"items":[{"word":"vorbei","translation":"past","pronunciation":"for-BY","example":"An der Post vorbei."},{"word":"die Ecke","translation":"corner","pronunciation":"dee EK-keh","example":"An der Ecke links."},{"word":"ungefähr","translation":"approximately","pronunciation":"OON-geh-fer","example":"Ungefähr 10 Minuten."},{"word":"entfernt","translation":"away (distance)","pronunciation":"ent-FERNT","example":"Es ist weit entfernt."},{"word":"die Kreuzung","translation":"crossroads","pronunciation":"dee KROY-tsoong","example":"An der Kreuzung rechts."},{"word":"gegenüber","translation":"opposite","pronunciation":"GAY-gen-ü-ber","example":"Gegenüber der Bank."}]}',
'{"title":"An + dative for location landmarks","pattern":"an der/dem + landmark + direction","explanation":"Use an der (f/pl) or an dem/am (m/n) to give directions relative to landmarks. Gehen Sie an der Kirche vorbei = Go past the church. An der Kreuzung links = left at the crossroads.","examples":[{"sentence":"An der Ampel rechts abbiegen.","translation":"Turn right at the traffic light."},{"sentence":"Es ist gegenüber dem Bahnhof.","translation":"It is opposite the train station."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Kreuzung'' means?","options":["crossroads","corner","street","junction"],"correctAnswer":"crossroads"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Go past the church.","options":["Gehen Sie an der Kirche vorbei.","Biegen Sie links ab.","Es ist gegenüber.","An der Ecke rechts."],"correctAnswer":"Gehen Sie an der Kirche vorbei."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es ist ___ 200 Meter entfernt.","options":["ungefähr","genau","fast","sehr"],"correctAnswer":"ungefähr"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Turn right at the crossroads","wordBankItems":["An","der","Kreuzung","rechts","abbiegen","."],"correctAnswer":"An der Kreuzung rechts abbiegen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gegenüber'' means?","options":["opposite","next to","behind","in front of"],"correctAnswer":"opposite"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000003f',1,'APPROVED','PUBLISHED',
'{"objectives":["Read a bus and train timetable","Ask about departure times","Use um and ab for times"],"explanation":{"intro":"Germany has excellent public transport. Being able to read timetables and ask about departures is essential for getting around.","culturalNote":"Deutsche Bahn (DB) is the national rail operator. Trains are generally punctual — a delay of more than 5 minutes is announced. Download the DB Navigator app."},"examples":[{"german":"Wann fährt der nächste Zug ab?","english":"When does the next train depart?"},{"german":"Der Bus fährt um 14:30 Uhr ab.","english":"The bus departs at 14:30."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can read a timetable and ask about departure times."}}',
'{"items":[{"word":"der Fahrplan","translation":"timetable","pronunciation":"dayr FAR-plahn","example":"Haben Sie einen Fahrplan?"},{"word":"abfahren","translation":"to depart","pronunciation":"AP-fah-ren","example":"Der Zug fährt ab."},{"word":"ankommen","translation":"to arrive","pronunciation":"AN-kom-en","example":"Wann kommen wir an?"},{"word":"der Anschluss","translation":"connection","pronunciation":"dayr AN-shloos","example":"Ich verpasse den Anschluss."},{"word":"das Gleis","translation":"platform/track","pronunciation":"dahs GLYS","example":"Gleis 7 bitte."},{"word":"pünktlich","translation":"on time","pronunciation":"PÜNNKT-likh","example":"Der Zug ist pünktlich."}]}',
'{"title":"Um vs. ab for time/departure","pattern":"um + time (at a specific time) / ab + station (departing from)","explanation":"Um gives the clock time: um 8 Uhr = at 8 o''clock. Abfahren is separable: fährt...ab. Wann fährt der Zug ab? = When does the train depart? Ab can also mean from: ab München = from Munich.","examples":[{"sentence":"Der Zug fährt um 10:15 Uhr ab.","translation":"The train departs at 10:15."},{"sentence":"Ab Hamburg dauert es zwei Stunden.","translation":"From Hamburg it takes two hours."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Gleis'' means?","options":["platform/track","timetable","connection","station"],"correctAnswer":"platform/track"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"When does the next train depart?","options":["Wann fährt der nächste Zug ab?","Wo ist der Bahnhof?","Ich verpasse den Anschluss.","Der Zug ist pünktlich."],"correctAnswer":"Wann fährt der nächste Zug ab?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Bus fährt ___ 14:30 Uhr ab.","options":["um","an","ab","bei"],"correctAnswer":"um"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The train is on time","wordBankItems":["Der","Zug","ist","pünktlich","."],"correctAnswer":"Der Zug ist pünktlich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Pünktlich'' means?","options":["on time","late","early","delayed"],"correctAnswer":"on time"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000040',1,'APPROVED','PUBLISHED',
'{"objectives":["Hail a taxi","Give an address as destination","Understand taxi phrases"],"explanation":{"intro":"Taxis in Germany are reliable but expensive. Ride-sharing apps like Uber also operate in major cities.","culturalNote":"German taxis are beige/cream coloured with a TAXI sign on top. You can hail them in the street, call by phone, or book via app."},"examples":[{"german":"Zum Hauptbahnhof, bitte.","english":"To the main station, please."},{"german":"Was macht das?","english":"How much is that?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can hail a taxi and give my destination."}}',
'{"items":[{"word":"das Taxi","translation":"taxi","pronunciation":"dahs TAK-see","example":"Ich nehme ein Taxi."},{"word":"der Fahrer","translation":"driver","pronunciation":"dayr FAH-rer","example":"Der Fahrer ist freundlich."},{"word":"zum","translation":"to the (dative contraction)","pronunciation":"TSOOM","example":"Zum Flughafen bitte."},{"word":"Was macht das?","translation":"How much is that?","pronunciation":"VAS MAKHT dahs","example":"Was macht das bitte?"},{"word":"der Umweg","translation":"detour","pronunciation":"dayr OOM-veg","example":"Bitte keinen Umweg."},{"word":"quittung","translation":"receipt","pronunciation":"KVIT-toong","example":"Eine Quittung bitte."}]}',
'{"title":"Zum / zur — to the (dative)","pattern":"zum (m/n) + destination / zur (f) + destination","explanation":"Zu + dem = zum (masculine/neuter), Zu + der = zur (feminine). Zum Bahnhof = to the station (der Bahnhof). Zur Post = to the post office (die Post). Zum Flughafen = to the airport (der Flughafen).","examples":[{"sentence":"Zur Uni bitte.","translation":"To the university please."},{"sentence":"Zum Hotel Adlon.","translation":"To Hotel Adlon."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Was macht das?'' means?","options":["How much is that?","What is that?","What does that do?","Is that correct?"],"correctAnswer":"How much is that?"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"To the airport please.","options":["Zum Flughafen bitte.","Zum Bahnhof bitte.","Zur Post bitte.","Was macht das?"],"correctAnswer":"Zum Flughafen bitte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ Hauptbahnhof, bitte.","options":["Zum","Zur","Zu","An"],"correctAnswer":"Zum"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A receipt please","wordBankItems":["Eine","Quittung","bitte","."],"correctAnswer":"Eine Quittung bitte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Umweg'' means?","options":["detour","shortcut","road","way"],"correctAnswer":"detour"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000041',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about cycling","Buy or rent a bike","Use Fahrrad idioms"],"explanation":{"intro":"Cycling is extremely popular in Germany. Many cities have excellent bike lanes and cycle paths.","culturalNote":"Germany has over 75,000 km of cycling paths. Cities like Münster, Freiburg and Hamburg are famous for their cycling culture."},"examples":[{"german":"Ich fahre mit dem Fahrrad zur Arbeit.","english":"I cycle to work."},{"german":"Wo kann ich ein Fahrrad leihen?","english":"Where can I rent a bike?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about cycling and ask about bike rental."}}',
'{"items":[{"word":"das Fahrrad","translation":"bicycle","pronunciation":"dahs FAR-raht","example":"Ich fahre Fahrrad."},{"word":"der Helm","translation":"helmet","pronunciation":"dayr HELM","example":"Trag immer einen Helm!"},{"word":"der Radweg","translation":"cycle path","pronunciation":"dayr RAHT-veg","example":"Hier ist ein Radweg."},{"word":"leihen","translation":"to borrow/rent","pronunciation":"LY-en","example":"Kann ich ein Rad leihen?"},{"word":"der Sattel","translation":"saddle","pronunciation":"dayr ZAT-tel","example":"Der Sattel ist zu hoch."},{"word":"eine Panne haben","translation":"to have a puncture","pronunciation":"EY-neh PAN-neh HAH-ben","example":"Ich habe eine Panne."}]}',
'{"title":"Mit dem Fahrrad — with the bicycle","pattern":"fahren mit dem Fahrrad (dative)","explanation":"Mit + dative is used for transport: mit dem Fahrrad, mit dem Auto, mit der U-Bahn. Fahrrad fahren also works as a compound: Ich fahre Fahrrad (no article — like sport: Ich spiele Tennis).","examples":[{"sentence":"Sie fährt mit dem Fahrrad zur Schule.","translation":"She cycles to school."},{"sentence":"Ich fahre lieber Fahrrad als Auto.","translation":"I prefer cycling to driving."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Radweg'' means?","options":["cycle path","road","helmet","saddle"],"correctAnswer":"cycle path"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I cycle to work.","options":["Ich fahre mit dem Fahrrad zur Arbeit.","Wo kann ich ein Rad leihen?","Ich habe eine Panne.","Der Helm ist wichtig."],"correctAnswer":"Ich fahre mit dem Fahrrad zur Arbeit."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Trag immer einen ___!","options":["Helm","Sattel","Radweg","Reifen"],"correctAnswer":"Helm"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Can I rent a bike?","wordBankItems":["Kann","ich","ein","Fahrrad","leihen","?"],"correctAnswer":"Kann ich ein Fahrrad leihen ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Eine Panne haben'' means?","options":["to have a puncture","to crash","to get lost","to stop"],"correctAnswer":"to have a puncture"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000042',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe walking routes","Use spazieren gehen","Talk about distances on foot"],"explanation":{"intro":"Walking is the simplest form of transport. Learn to describe walking distances and invite people for a stroll.","culturalNote":"The Spaziergang (leisurely walk) is a beloved German tradition especially on Sunday afternoons. Whole families go for a Sonntagsspaziergang after lunch."},"examples":[{"german":"Gehen wir spazieren?","english":"Shall we go for a walk?"},{"german":"Es ist zu Fuß erreichbar.","english":"It is reachable on foot."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about walking and suggest a walk."}}',
'{"items":[{"word":"spazieren gehen","translation":"to go for a walk","pronunciation":"shpah-TSEER-en GAY-en","example":"Ich gehe spazieren."},{"word":"zu Fuß","translation":"on foot","pronunciation":"tsoo FOOS","example":"Ich gehe zu Fuß."},{"word":"der Spaziergang","translation":"walk/stroll","pronunciation":"dayr shpah-TSEER-gang","example":"Ein Spaziergang im Park."},{"word":"erreichbar","translation":"reachable","pronunciation":"er-RY-khbar","example":"Zu Fuß erreichbar."},{"word":"der Park","translation":"park","pronunciation":"dayr PARK","example":"Im Park spazieren."},{"word":"die Strecke","translation":"route/distance","pronunciation":"dee SHTREK-keh","example":"Die Strecke ist kurz."}]}',
'{"title":"Zu Fuß vs. mit dem... — transport modes","pattern":"zu Fuß (on foot) / mit dem Auto (by car) / mit dem Rad (by bike)","explanation":"Zu Fuß is the only transport mode using zu rather than mit. All other transport modes use mit + dem/der + vehicle. Zu Fuß erreichbar = reachable on foot. Zu Fuß gehen = to walk.","examples":[{"sentence":"Ich komme zu Fuß.","translation":"I am coming on foot."},{"sentence":"Bist du mit dem Auto oder zu Fuß?","translation":"Are you by car or on foot?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Spaziergang'' means?","options":["walk/stroll","park","route","distance"],"correctAnswer":"walk/stroll"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Shall we go for a walk?","options":["Gehen wir spazieren?","Ich gehe zu Fuß.","Die Strecke ist kurz.","Im Park ist es schön."],"correctAnswer":"Gehen wir spazieren?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es ist ___ Fuß erreichbar.","options":["zu","mit","per","auf"],"correctAnswer":"zu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A walk in the park","wordBankItems":["Ein","Spaziergang","im","Park","."],"correctAnswer":"Ein Spaziergang im Park ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erreichbar'' means?","options":["reachable","walkable","close","possible"],"correctAnswer":"reachable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000043',1,'APPROVED','PUBLISHED',
'{"objectives":["Use car travel vocabulary","Talk about road rules","Use Auto fahren"],"explanation":{"intro":"Germany is home to the Autobahn, one of the world famous motorway systems. Car vocabulary is essential for drivers and passengers alike.","culturalNote":"Parts of the German Autobahn have no speed limit. However 70% does have limits. The recommended speed is 130 km/h. Slow driving in the fast lane is illegal."},"examples":[{"german":"Ich fahre auf der Autobahn.","english":"I am driving on the motorway."},{"german":"Wir tanken beim nächsten Bahnhof.","english":"We will fill up at the next service station."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about car travel and road trips."}}',
'{"items":[{"word":"die Autobahn","translation":"motorway","pronunciation":"dee OW-toh-bahn","example":"Auf der Autobahn fahren."},{"word":"tanken","translation":"to fill up (fuel)","pronunciation":"TAN-ken","example":"Wir müssen tanken."},{"word":"die Tankstelle","translation":"petrol station","pronunciation":"dee TANK-shtel-leh","example":"Die Tankstelle ist rechts."},{"word":"das Navi","translation":"sat nav / GPS","pronunciation":"dahs NAH-vee","example":"Das Navi zeigt den Weg."},{"word":"der Stau","translation":"traffic jam","pronunciation":"dayr SHTOW","example":"Es gibt einen Stau."},{"word":"überholen","translation":"to overtake","pronunciation":"ü-ber-HOH-len","example":"Darf ich überholen?"}]}',
'{"title":"Es gibt einen Stau — reporting traffic","pattern":"Es gibt + accusative noun (traffic report)","explanation":"Es gibt is used to report what exists on the road. Es gibt einen Stau = There is a traffic jam. Es gibt eine Baustelle = There is a roadworks. Es gibt + accusative is a fixed construction.","examples":[{"sentence":"Es gibt eine Umleitung.","translation":"There is a diversion."},{"sentence":"Gibt es Stau auf der A9?","translation":"Is there a traffic jam on the A9?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Stau'' means?","options":["traffic jam","motorway","service station","diversion"],"correctAnswer":"traffic jam"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We need to fill up.","options":["Wir müssen tanken.","Es gibt einen Stau.","Fahr auf der Autobahn.","Das Navi zeigt den Weg."],"correctAnswer":"Wir müssen tanken."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es gibt ___ Stau.","options":["einen","ein","eine","der"],"correctAnswer":"einen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The sat nav shows the way","wordBankItems":["Das","Navi","zeigt","den","Weg","."],"correctAnswer":"Das Navi zeigt den Weg ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Tanken'' means?","options":["to fill up","to drive","to park","to overtake"],"correctAnswer":"to fill up"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000044',1,'APPROVED','PUBLISHED',
'{"objectives":["Search for an apartment","Understand rental vocabulary","Use suchen and mieten"],"explanation":{"intro":"Renting an apartment in Germany requires specific vocabulary. The rental market is competitive, especially in cities like Berlin, Munich and Hamburg.","culturalNote":"German rental contracts (Mietvertrag) are detailed. Nebenkosten (additional costs for utilities) are usually on top of the base rent (Kaltmiete)."},"examples":[{"german":"Ich suche eine Zweizimmerwohnung.","english":"I am looking for a two-room apartment."},{"german":"Wie hoch ist die Miete?","english":"How high is the rent?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can search for and ask about apartment rentals."}}',
'{"items":[{"word":"die Wohnung","translation":"apartment/flat","pronunciation":"dee VOH-noong","example":"Ich suche eine Wohnung."},{"word":"die Miete","translation":"rent","pronunciation":"dee MEE-teh","example":"Die Miete ist hoch."},{"word":"mieten","translation":"to rent","pronunciation":"MEE-ten","example":"Ich möchte mieten."},{"word":"die Nebenkosten","translation":"utility costs","pronunciation":"dee NAY-ben-kos-ten","example":"Nebenkosten inklusive?"},{"word":"der Vermieter","translation":"landlord","pronunciation":"dayr fer-MEE-ter","example":"Der Vermieter ist nett."},{"word":"die Kaution","translation":"deposit","pronunciation":"dee kow-TSYOHN","example":"Drei Monatsmieten Kaution."}]}',
'{"title":"Suchen nach vs. suchen + direct object","pattern":"ich suche + accusative (looking for something specific)","explanation":"Suchen takes the accusative directly: Ich suche eine Wohnung = I am looking for a flat. Note: suchen nach + dative is also possible for searching for something abstract: Ich suche nach einer Lösung = I am looking for a solution.","examples":[{"sentence":"Wir suchen eine Dreizimmerwohnung.","translation":"We are looking for a three-room flat."},{"sentence":"Suchen Sie eine möblierte Wohnung?","translation":"Are you looking for a furnished flat?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Kaution'' means?","options":["deposit","rent","costs","contract"],"correctAnswer":"deposit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"How high is the rent?","options":["Wie hoch ist die Miete?","Ich suche eine Wohnung.","Nebenkosten inklusive?","Der Vermieter ist nett."],"correctAnswer":"Wie hoch ist die Miete?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich suche ___ Zweizimmerwohnung.","options":["eine","ein","einen","der"],"correctAnswer":"eine"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Utility costs included?","wordBankItems":["Nebenkosten","inklusive","?"],"correctAnswer":"Nebenkosten inklusive ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Vermieter'' means?","options":["landlord","tenant","agent","neighbour"],"correctAnswer":"landlord"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000045',1,'APPROVED','PUBLISHED',
'{"objectives":["Name furniture items","Describe room layout","Use stehen and liegen for position"],"explanation":{"intro":"Furniture vocabulary lets you describe your home, shop for furnishings, and discuss interior design.","culturalNote":"IKEA, though Swedish, is enormously popular in Germany. Many Germans also shop at second-hand furniture shops (Möbelrestaurant or Secondhand-Laden)."},"examples":[{"german":"Das Sofa steht vor dem Fenster.","english":"The sofa stands in front of the window."},{"german":"Ich brauche einen neuen Schrank.","english":"I need a new wardrobe."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name furniture and describe where things are positioned."}}',
'{"items":[{"word":"das Sofa","translation":"sofa","pronunciation":"dahs ZOH-fah","example":"Ich sitze auf dem Sofa."},{"word":"der Schrank","translation":"wardrobe/cupboard","pronunciation":"dayr SHRANK","example":"Der Schrank ist voll."},{"word":"der Tisch","translation":"table","pronunciation":"dayr TISH","example":"Am Tisch essen."},{"word":"das Regal","translation":"shelf/bookcase","pronunciation":"dahs reh-GAHL","example":"Das Regal ist neu."},{"word":"stehen","translation":"to stand (position of objects)","pronunciation":"SHTAY-en","example":"Der Tisch steht hier."},{"word":"vor dem","translation":"in front of (dative)","pronunciation":"FOR dem","example":"Vor dem Fenster."}]}',
'{"title":"Stehen/liegen/hängen — object positions","pattern":"stehen (upright), liegen (flat), hängen (hanging)","explanation":"German uses specific verbs for how objects are positioned. Stehen = upright objects (lamps, wardrobes). Liegen = flat objects (books, rugs). Hängen = hanging objects (pictures, coats). Das Bild hängt an der Wand = The picture hangs on the wall.","examples":[{"sentence":"Der Teppich liegt auf dem Boden.","translation":"The rug lies on the floor."},{"sentence":"Das Bild hängt an der Wand.","translation":"The picture hangs on the wall."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Regal'' means?","options":["shelf/bookcase","wardrobe","table","sofa"],"correctAnswer":"shelf/bookcase"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The sofa stands in front of the window.","options":["Das Sofa steht vor dem Fenster.","Der Tisch steht in der Mitte.","Das Regal ist neu.","Ich brauche einen Schrank."],"correctAnswer":"Das Sofa steht vor dem Fenster."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Bild ___ an der Wand.","options":["hängt","steht","liegt","ist"],"correctAnswer":"hängt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The table stands in the middle","wordBankItems":["Der","Tisch","steht","in","der","Mitte","."],"correctAnswer":"Der Tisch steht in der Mitte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vor dem'' means?","options":["in front of","behind","next to","above"],"correctAnswer":"in front of"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000046',1,'APPROVED','PUBLISHED',
'{"objectives":["Name kitchen items and appliances","Talk about cooking equipment","Use benutzen and funktionieren"],"explanation":{"intro":"Kitchen vocabulary is essential for cooking and shopping for appliances.","culturalNote":"German kitchens are famously not included in rental apartments — tenants bring their own Einbauküche (fitted kitchen). This surprises many foreign renters!"},"examples":[{"german":"Der Herd hat vier Herdplatten.","english":"The stove has four burners."},{"german":"Die Spülmaschine ist kaputt.","english":"The dishwasher is broken."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name kitchen items and talk about appliances."}}',
'{"items":[{"word":"der Herd","translation":"cooker/stove","pronunciation":"dayr HAYRT","example":"Am Herd kochen."},{"word":"der Kühlschrank","translation":"fridge","pronunciation":"dayr KÜL-shrank","example":"Im Kühlschrank ist Essen."},{"word":"die Spülmaschine","translation":"dishwasher","pronunciation":"dee SHPÜL-mah-shee-neh","example":"Die Spülmaschine läuft."},{"word":"der Topf","translation":"pot/saucepan","pronunciation":"dayr TOPF","example":"Im Topf kocht Suppe."},{"word":"kaputt","translation":"broken","pronunciation":"kah-POOT","example":"Das Gerät ist kaputt."},{"word":"die Pfanne","translation":"frying pan","pronunciation":"dee PFAN-neh","example":"In der Pfanne braten."}]}',
'{"title":"Kaputt sein — broken/not working","pattern":"etwas ist kaputt / funktioniert nicht","explanation":"Kaputt means broken or not working. Die Waschmaschine ist kaputt = The washing machine is broken. Funktionieren nicht is more formal: Der Aufzug funktioniert nicht = The lift is not working.","examples":[{"sentence":"Mein Handy ist kaputt.","translation":"My phone is broken."},{"sentence":"Der Herd funktioniert nicht.","translation":"The stove is not working."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Kühlschrank'' means?","options":["fridge","stove","dishwasher","oven"],"correctAnswer":"fridge"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The dishwasher is broken.","options":["Die Spülmaschine ist kaputt.","Der Herd funktioniert nicht.","Im Topf kocht Suppe.","Die Pfanne ist neu."],"correctAnswer":"Die Spülmaschine ist kaputt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gerät ist ___.","options":["kaputt","neu","groß","teuer"],"correctAnswer":"kaputt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In the pot soup is cooking","wordBankItems":["Im","Topf","kocht","Suppe","."],"correctAnswer":"Im Topf kocht Suppe ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Herd'' means?","options":["cooker/stove","fridge","oven","microwave"],"correctAnswer":"cooker/stove"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000047',1,'APPROVED','PUBLISHED',
'{"objectives":["Name bathroom items","Describe bathroom routine","Use sich waschen"],"explanation":{"intro":"Bathroom vocabulary builds on the reflexive verbs from the morning routine lesson. Learn to describe what is in a bathroom and talk about personal hygiene.","culturalNote":"German pharmacies and DM (drugstore chain) sell a wide range of bathroom products. DM and Rossmann are the two main drugstore chains."},"examples":[{"german":"Ich wasche mir die Hände.","english":"I wash my hands."},{"german":"Das Handtuch hängt am Haken.","english":"The towel hangs on the hook."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name bathroom items and describe personal hygiene routines."}}',
'{"items":[{"word":"das Handtuch","translation":"towel","pronunciation":"dahs HANT-tookh","example":"Ein sauberes Handtuch."},{"word":"die Seife","translation":"soap","pronunciation":"dee ZY-feh","example":"Hände mit Seife waschen."},{"word":"das Shampoo","translation":"shampoo","pronunciation":"dahs sham-POO","example":"Ich wasche die Haare mit Shampoo."},{"word":"der Spiegel","translation":"mirror","pronunciation":"dayr SHPEE-gel","example":"Im Spiegel schauen."},{"word":"die Zahnbürste","translation":"toothbrush","pronunciation":"dee TSAHN-bürs-teh","example":"Ich putze Zähne."},{"word":"sich waschen","translation":"to wash oneself","pronunciation":"zikh VAH-shen","example":"Ich wasche mich."}]}',
'{"title":"Mir vs. mich — dative vs. accusative reflexive","pattern":"ich wasche mich (acc.) / ich wasche mir die Hände (dat. + body part)","explanation":"When a body part is the object, use dative reflexive (mir/dir/sich) + body part. Ich wasche mir die Hände = I wash my hands (lit. I wash myself the hands). Without a body part, use accusative: Ich wasche mich = I wash myself.","examples":[{"sentence":"Ich putze mir die Zähne.","translation":"I brush my teeth."},{"sentence":"Er wäscht sich das Gesicht.","translation":"He washes his face."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Zahnbürste'' means?","options":["toothbrush","toothpaste","towel","soap"],"correctAnswer":"toothbrush"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I wash my hands.","options":["Ich wasche mir die Hände.","Ich wasche mich.","Das Handtuch ist nass.","Die Seife ist gut."],"correctAnswer":"Ich wasche mir die Hände."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich putze ___ die Zähne.","options":["mir","mich","sich","dich"],"correctAnswer":"mir"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A clean towel","wordBankItems":["Ein","sauberes","Handtuch","."],"correctAnswer":"Ein sauberes Handtuch ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Spiegel'' means?","options":["mirror","window","picture","shelf"],"correctAnswer":"mirror"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000048',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about a garden","Name garden plants and tools","Use im Garten for location"],"explanation":{"intro":"Many Germans are enthusiastic gardeners. Even apartment dwellers often have a Schrebergarten (allotment) to grow vegetables and flowers.","culturalNote":"Schrebergärten (allotments) are very popular in Germany. There are over 900,000 allotment plots. They are a tradition going back to the 19th century."},"examples":[{"german":"Ich arbeite gern im Garten.","english":"I like working in the garden."},{"german":"Die Rosen blühen im Sommer.","english":"The roses bloom in summer."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about a garden and name plants and tools."}}',
'{"items":[{"word":"der Garten","translation":"garden","pronunciation":"dayr GAR-ten","example":"Im Garten ist es schön."},{"word":"die Rose","translation":"rose","pronunciation":"dee ROH-zeh","example":"Die Rosen sind rot."},{"word":"gießen","translation":"to water (plants)","pronunciation":"GEE-sen","example":"Ich gieße die Blumen."},{"word":"der Rasenmäher","translation":"lawnmower","pronunciation":"dayr RAH-zen-may-er","example":"Ich mähe den Rasen."},{"word":"pflanzen","translation":"to plant","pronunciation":"PFLAN-tsen","example":"Ich pflanze Tomaten."},{"word":"das Unkraut","translation":"weeds","pronunciation":"dahs OON-krowt","example":"Das Unkraut jäten."}]}',
'{"title":"Separable: mähen, gießen, jäten — garden chores","pattern":"den Rasen mähen / die Blumen gießen / das Unkraut jäten","explanation":"Garden chores use specific verb + object combinations. Den Rasen mähen = to mow the lawn. Die Blumen gießen = to water the flowers. Das Unkraut jäten = to weed. These are standard fixed phrases used by German gardeners.","examples":[{"sentence":"Ich muss heute den Rasen mähen.","translation":"I must mow the lawn today."},{"sentence":"Hast du die Blumen gegossen?","translation":"Have you watered the flowers?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Unkraut'' means?","options":["weeds","grass","flowers","plants"],"correctAnswer":"weeds"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like working in the garden.","options":["Ich arbeite gern im Garten.","Die Rosen blühen.","Ich gieße die Blumen.","Der Garten ist groß."],"correctAnswer":"Ich arbeite gern im Garten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ die Blumen.","options":["gieße","pflanze","mähe","jäte"],"correctAnswer":"gieße"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am planting tomatoes","wordBankItems":["Ich","pflanze","Tomaten","."],"correctAnswer":"Ich pflanze Tomaten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gießen'' means?","options":["to water","to plant","to mow","to weed"],"correctAnswer":"to water"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000049',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk to neighbours","Use polite neighbour phrases","Discuss noise and shared spaces"],"explanation":{"intro":"Good neighbourly relations are important in Germany. Learning to communicate with neighbours avoids conflicts and builds community.","culturalNote":"Germans are known for their Ruhezeiten (quiet hours) — typically 10pm to 7am and Sundays all day. Making noise during these times is antisocial and can result in complaints."},"examples":[{"german":"Guten Morgen, Herr Schmidt!","english":"Good morning, Mr Schmidt!"},{"german":"Es tut mir leid wegen des Lärms.","english":"I am sorry about the noise."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can communicate politely with my neighbours."}}',
'{"items":[{"word":"der Nachbar","translation":"neighbour (m)","pronunciation":"dayr NAKH-bar","example":"Mein Nachbar ist freundlich."},{"word":"der Lärm","translation":"noise","pronunciation":"dayr LERM","example":"Der Lärm stört mich."},{"word":"die Ruhezeit","translation":"quiet hours","pronunciation":"dee ROO-eh-tsyt","example":"Das ist Ruhezeit."},{"word":"stören","translation":"to disturb","pronunciation":"SHTÖ-ren","example":"Störe ich?"},{"word":"klingeln","translation":"to ring the doorbell","pronunciation":"KLING-eln","example":"Ich klingle an der Tür."},{"word":"wegen","translation":"because of/due to","pronunciation":"VAY-gen","example":"Wegen des Lärms."}]}',
'{"title":"Wegen + genitive — because of","pattern":"wegen + genitive noun","explanation":"Wegen means because of or due to. It takes the genitive case: wegen des Lärms (genitive of der Lärm). In spoken German, dative is also common: wegen dem Lärm. Both are heard but genitive is formally correct.","examples":[{"sentence":"Wegen des Wetters bleibe ich zu Hause.","translation":"Because of the weather I am staying home."},{"sentence":"Entschuldigung wegen des Lärms.","translation":"Sorry because of the noise."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Ruhezeit'' means?","options":["quiet hours","rest time","sleep time","break time"],"correctAnswer":"quiet hours"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am sorry about the noise.","options":["Es tut mir leid wegen des Lärms.","Der Nachbar stört mich.","Ich klingle an der Tür.","Störe ich?"],"correctAnswer":"Es tut mir leid wegen des Lärms."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Lärm ___ mich.","options":["stört","klingelt","wegen","hilft"],"correctAnswer":"stört"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My neighbour is friendly","wordBankItems":["Mein","Nachbar","ist","freundlich","."],"correctAnswer":"Mein Nachbar ist freundlich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wegen'' means?","options":["because of","with","without","against"],"correctAnswer":"because of"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000004a',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about moving house","Use Umzug vocabulary","Describe packing and unpacking"],"explanation":{"intro":"Moving house (Umzug) is a stressful but common experience. Knowing the vocabulary helps you organise your move and ask for help.","culturalNote":"It is common in Germany to hire a Umzugsunternehmen (removal company). Friends often help in exchange for pizza and beer — a Umzugsparty!"},"examples":[{"german":"Ich ziehe nächsten Monat um.","english":"I am moving next month."},{"german":"Kannst du mir beim Umzug helfen?","english":"Can you help me with the move?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about moving house and ask for help."}}',
'{"items":[{"word":"umziehen","translation":"to move house","pronunciation":"OOM-tsee-en","example":"Ich ziehe um."},{"word":"der Umzug","translation":"move/removal","pronunciation":"dayr OOM-tsook","example":"Der Umzug ist stressig."},{"word":"einpacken","translation":"to pack up","pronunciation":"YN-pak-en","example":"Ich packe die Kartons ein."},{"word":"auspacken","translation":"to unpack","pronunciation":"OWS-pak-en","example":"Ich packe alles aus."},{"word":"die Karton","translation":"cardboard box","pronunciation":"dee kar-TOHN","example":"Viele Kartons!"},{"word":"das Umzugsunternehmen","translation":"removal company","pronunciation":"dahs OOM-tsooks-oon-ter-nay-men","example":"Wir mieten ein Umzugsunternehmen."}]}',
'{"title":"Umziehen — separable verb for moving","pattern":"ich ziehe um / du ziehst um / er zieht um","explanation":"Umziehen has two meanings: to move house (um + ziehen) and to change clothes (sich umziehen). Context determines meaning. Ich ziehe um = I am moving. Ich ziehe mich um = I am changing clothes.","examples":[{"sentence":"Wann ziehst du um?","translation":"When are you moving?"},{"sentence":"Ich muss mich umziehen.","translation":"I must get changed."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Einpacken'' means?","options":["to pack up","to unpack","to move","to carry"],"correctAnswer":"to pack up"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am moving next month.","options":["Ich ziehe nächsten Monat um.","Ich packe die Kartons ein.","Der Umzug ist stressig.","Kannst du helfen?"],"correctAnswer":"Ich ziehe nächsten Monat um."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich packe alles ___.","options":["aus","ein","um","ab"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The move is stressful","wordBankItems":["Der","Umzug","ist","stressig","."],"correctAnswer":"Der Umzug ist stressig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Auspacken'' means?","options":["to unpack","to pack","to move","to carry"],"correctAnswer":"to unpack"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000004b',1,'APPROVED','PUBLISHED',
'{"objectives":["Use a smartphone in German","Describe common phone actions","Use anrufen and aufladen"],"explanation":{"intro":"Smartphone vocabulary is essential in modern life. Learn the verbs and nouns for everyday mobile phone use.","culturalNote":"Germany has high smartphone penetration. WhatsApp is the dominant messaging app — text messages (SMS) are rarely used."},"examples":[{"german":"Ich lade mein Handy auf.","english":"I am charging my phone."},{"german":"Ruf mich an!","english":"Call me!"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe common smartphone actions in German."}}',
'{"items":[{"word":"aufladen","translation":"to charge","pronunciation":"OWF-lah-den","example":"Ich lade das Handy auf."},{"word":"anrufen","translation":"to call","pronunciation":"AN-roo-fen","example":"Ich rufe dich an."},{"word":"die Nachricht","translation":"message","pronunciation":"dee NAKH-rikht","example":"Ich schicke eine Nachricht."},{"word":"der Akku","translation":"battery","pronunciation":"dayr AK-koo","example":"Der Akku ist leer."},{"word":"WLAN","translation":"WiFi","pronunciation":"VAY-lahn","example":"Gibt es WLAN hier?"},{"word":"installieren","translation":"to install (an app)","pronunciation":"in-stah-LEER-en","example":"Ich installiere die App."}]}',
'{"title":"Anrufen and aufladen — separable verbs","pattern":"ich rufe an / ich lade auf","explanation":"Both anrufen and aufladen are separable. The prefix splits to the end. Ich rufe dich an = I am calling you. Ich lade das Handy auf = I am charging the phone. In the infinitive: anrufen, aufladen.","examples":[{"sentence":"Kannst du mich anrufen?","translation":"Can you call me?"},{"sentence":"Ich muss das Handy aufladen.","translation":"I need to charge the phone."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Akku'' means?","options":["battery","charger","WiFi","signal"],"correctAnswer":"battery"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am charging my phone.","options":["Ich lade mein Handy auf.","Ich rufe dich an.","Der Akku ist leer.","Gibt es WLAN?"],"correctAnswer":"Ich lade mein Handy auf."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich rufe dich ___.","options":["an","auf","ab","aus"],"correctAnswer":"an"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The battery is empty","wordBankItems":["Der","Akku","ist","leer","."],"correctAnswer":"Der Akku ist leer ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''WLAN'' means?","options":["WiFi","mobile data","Bluetooth","network"],"correctAnswer":"WiFi"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000004c',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe computer tasks","Use German computing vocabulary","Talk about files and programs"],"explanation":{"intro":"Computer vocabulary is essential in professional and everyday life. Many English terms are used in German computing but there are German equivalents too.","culturalNote":"Germany has strict data protection laws (Datenschutz). GDPR (DSGVO in German) is taken very seriously. Websites must clearly explain cookie usage."},"examples":[{"german":"Ich öffne die Datei.","english":"I open the file."},{"german":"Das Programm hat sich aufgehängt.","english":"The programme has frozen."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe common computer tasks in German."}}',
'{"items":[{"word":"die Datei","translation":"file","pronunciation":"dee dah-TY","example":"Ich speichere die Datei."},{"word":"speichern","translation":"to save","pronunciation":"SHPY-khern","example":"Vergiss nicht zu speichern!"},{"word":"das Passwort","translation":"password","pronunciation":"dahs PAS-vort","example":"Das Passwort ist falsch."},{"word":"drucken","translation":"to print","pronunciation":"DROO-ken","example":"Ich drucke das Dokument."},{"word":"herunterladen","translation":"to download","pronunciation":"her-OON-ter-lah-den","example":"Ich lade die Datei herunter."},{"word":"das Dokument","translation":"document","pronunciation":"dahs doh-koo-MENT","example":"Das Dokument ist fertig."}]}',
'{"title":"Herunterladen — long separable verb","pattern":"ich lade herunter / du lädst herunter","explanation":"Herunterladen (to download) is a separable verb with a long prefix. Ich lade die Datei herunter. The base verb is laden, the prefix is herunter. Note the vowel change: ich lade but du lädst (umlaut). Hochladen (to upload) works the same: ich lade hoch.","examples":[{"sentence":"Ich lade das Update herunter.","translation":"I am downloading the update."},{"sentence":"Sie lädt das Dokument hoch.","translation":"She is uploading the document."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Speichern'' means?","options":["to save","to open","to close","to print"],"correctAnswer":"to save"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am downloading the file.","options":["Ich lade die Datei herunter.","Ich speichere das Dokument.","Das Passwort ist falsch.","Ich drucke es aus."],"correctAnswer":"Ich lade die Datei herunter."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Vergiss nicht zu ___!","options":["speichern","drucken","laden","öffnen"],"correctAnswer":"speichern"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The document is ready","wordBankItems":["Das","Dokument","ist","fertig","."],"correctAnswer":"Das Dokument ist fertig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Passwort'' means?","options":["password","username","email","code"],"correctAnswer":"password"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000004d',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about internet use","Describe online activities","Use surfen and posten"],"explanation":{"intro":"Internet vocabulary is essential for modern communication. Learn the German terms for common online activities.","culturalNote":"Germany has relatively slow average internet speeds compared to other European nations, a topic of ongoing political debate. Fibre rollout is expanding."},"examples":[{"german":"Ich surfe im Internet.","english":"I am browsing the internet."},{"german":"Ich suche das online.","english":"I am searching for that online."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe internet activities in German."}}',
'{"items":[{"word":"im Internet surfen","translation":"to browse the internet","pronunciation":"im IN-ter-net ZUR-fen","example":"Ich surfe im Internet."},{"word":"googeln","translation":"to google","pronunciation":"GOO-geln","example":"Ich google das."},{"word":"posten","translation":"to post (online)","pronunciation":"POS-ten","example":"Er postet ein Foto."},{"word":"die Website","translation":"website","pronunciation":"dee VEB-syte","example":"Die Website ist toll."},{"word":"das Passwort","translation":"password","pronunciation":"dahs PAS-vort","example":"Ich vergesse das Passwort."},{"word":"online","translation":"online","pronunciation":"ON-line","example":"Ich bin online."}]}',
'{"title":"Ich bin online — state expressions","pattern":"ich bin + online/offline/verfügbar","explanation":"Use sein to describe connection states: Ich bin online = I am online. Ich bin offline = I am offline. Ich bin nicht erreichbar = I am not reachable. These are common in both personal and professional contexts.","examples":[{"sentence":"Ich bin nicht online.","translation":"I am not online."},{"sentence":"Bist du gerade verfügbar?","translation":"Are you available right now?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Googeln'' means?","options":["to google","to post","to browse","to download"],"correctAnswer":"to google"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"He is posting a photo.","options":["Er postet ein Foto.","Ich surfe im Internet.","Die Website ist gut.","Ich bin online."],"correctAnswer":"Er postet ein Foto."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ das Internet.","options":["surfe im","poste","google","lade"],"correctAnswer":"surfe im"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am browsing the internet","wordBankItems":["Ich","surfe","im","Internet","."],"correctAnswer":"Ich surfe im Internet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Posten'' means?","options":["to post online","to send","to browse","to share"],"correctAnswer":"to post online"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000004e',1,'APPROVED','PUBLISHED',
'{"objectives":["Use social media vocabulary","Talk about followers and likes","Use teilen and folgen"],"explanation":{"intro":"Social media is a major part of modern communication. Learn the German vocabulary for platforms and interactions.","culturalNote":"Instagram, YouTube and TikTok are the dominant platforms for younger Germans. Facebook remains popular with older demographics. Twitter/X has a smaller but active German user base."},"examples":[{"german":"Ich folge dir auf Instagram.","english":"I follow you on Instagram."},{"german":"Das Video hat eine Million Aufrufe.","english":"The video has one million views."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about social media in German."}}',
'{"items":[{"word":"folgen","translation":"to follow","pronunciation":"FOL-gen","example":"Ich folge dir."},{"word":"teilen","translation":"to share","pronunciation":"TY-len","example":"Ich teile den Post."},{"word":"liken","translation":"to like","pronunciation":"LY-ken","example":"Ich like das Foto."},{"word":"der Aufruf","translation":"view (video)","pronunciation":"dayr OWF-roof","example":"Viele Aufrufe!"},{"word":"der Follower","translation":"follower","pronunciation":"dayr FOL-oh-er","example":"Ich habe viele Follower."},{"word":"der Beitrag","translation":"post/contribution","pronunciation":"dayr BY-trahk","example":"Ich schreibe einen Beitrag."}]}',
'{"title":"Folgen + dative — to follow someone","pattern":"ich folge + dative person","explanation":"Folgen (to follow) takes the dative case for the person followed. Ich folge dir = I follow you. Ich folge ihm = I follow him. This is different from folgen in the sense of following a path, where accusative is used.","examples":[{"sentence":"Ich folge ihr auf TikTok.","translation":"I follow her on TikTok."},{"sentence":"Folgst du mir?","translation":"Do you follow me?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Teilen'' means?","options":["to share","to like","to follow","to post"],"correctAnswer":"to share"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I follow you on Instagram.","options":["Ich folge dir auf Instagram.","Ich like dein Foto.","Ich teile den Beitrag.","Viele Aufrufe!"],"correctAnswer":"Ich folge dir auf Instagram."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ das Foto.","options":["like","folge","teile","poste"],"correctAnswer":"like"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have many followers","wordBankItems":["Ich","habe","viele","Follower","."],"correctAnswer":"Ich habe viele Follower ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Beitrag'' means?","options":["post/contribution","follower","view","like"],"correctAnswer":"post/contribution"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000004f',1,'APPROVED','PUBLISHED',
'{"objectives":["Write a basic email in German","Use formal email openings and closings","Structure an email"],"explanation":{"intro":"Email writing is an essential professional skill. German emails follow specific conventions for formal and informal communication.","culturalNote":"German business emails are formal. Always use Sehr geehrte/r (Dear) for unknown recipients. Avoid starting with the word Ich (I) — it is considered rude in formal writing."},"examples":[{"german":"Sehr geehrte Damen und Herren,","english":"Dear Sir/Madam,"},{"german":"Mit freundlichen Grüßen","english":"Kind regards"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can write a basic formal email in German."}}',
'{"items":[{"word":"Sehr geehrte/r","translation":"Dear (formal)","pronunciation":"zayr geh-AYR-teh","example":"Sehr geehrter Herr Müller,"},{"word":"Mit freundlichen Grüßen","translation":"Kind regards","pronunciation":"mit FROYN-dlikh-en GRÜS-en","example":"Mit freundlichen Grüßen"},{"word":"der Betreff","translation":"subject line","pronunciation":"dayr beh-TREF","example":"Betreff: Anfrage"},{"word":"der Anhang","translation":"attachment","pronunciation":"dayr AN-hang","example":"Im Anhang finden Sie..."},{"word":"beigefügt","translation":"attached/enclosed","pronunciation":"BY-geh-fügt","example":"Anbei beigefügt."},{"word":"die Anfrage","translation":"enquiry/request","pronunciation":"dee AN-frah-geh","example":"Ich habe eine Anfrage."}]}',
'{"title":"Formal email structure","pattern":"Sehr geehrte/r... → body → Mit freundlichen Grüßen","explanation":"German formal emails: Start Sehr geehrte Frau X / Sehr geehrter Herr X. If unknown: Sehr geehrte Damen und Herren. Close with Mit freundlichen Grüßen (formal) or Viele Grüße (semi-formal). Avoid starting sentences with Ich.","examples":[{"sentence":"Anbei finden Sie die Unterlagen.","translation":"Please find the documents attached."},{"sentence":"Über eine Antwort würde ich mich freuen.","translation":"I would be pleased to receive a reply."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Anhang'' means?","options":["attachment","subject","signature","reply"],"correctAnswer":"attachment"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Kind regards","options":["Mit freundlichen Grüßen","Sehr geehrte Damen,","Viele Grüße","Auf Wiedersehen"],"correctAnswer":"Mit freundlichen Grüßen"},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ geehrter Herr Schmidt,","options":["Sehr","Viele","Mit","Herzliche"],"correctAnswer":"Sehr"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have an enquiry","wordBankItems":["Ich","habe","eine","Anfrage","."],"correctAnswer":"Ich habe eine Anfrage ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Betreff'' means?","options":["subject line","greeting","closing","body text"],"correctAnswer":"subject line"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000050',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe cold and flu symptoms","Buy medicine","Use bleiben + zu Hause"],"explanation":{"intro":"Colds and flu are common topics. Knowing how to describe symptoms helps you get the right medicine and explain absences.","culturalNote":"Germans take sick leave (Krankmeldung) seriously. You must call your employer on the first day of illness and get a doctor certificate (Krankenschein/AU) after 3 days."},"examples":[{"german":"Ich habe mich erkältet.","english":"I have caught a cold."},{"german":"Ich bleibe heute zu Hause.","english":"I am staying home today."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can describe cold and flu symptoms and explain an absence."}}',
'{"items":[{"word":"sich erkälten","translation":"to catch a cold","pronunciation":"zikh er-KEL-ten","example":"Ich habe mich erkältet."},{"word":"die Erkältung","translation":"cold (illness)","pronunciation":"dee er-KEL-toong","example":"Ich habe eine Erkältung."},{"word":"die Grippe","translation":"flu","pronunciation":"dee GRIP-peh","example":"Die Grippe ist schlimm."},{"word":"niesen","translation":"to sneeze","pronunciation":"NEE-zen","example":"Ich niese die ganze Zeit."},{"word":"die Krankmeldung","translation":"sick note","pronunciation":"dee KRANK-mel-doong","example":"Ich brauche eine Krankmeldung."},{"word":"erholen","translation":"to recover","pronunciation":"er-HOH-len","example":"Ich erhole mich."}]}',
'{"title":"Sich erkälten — reflexive illness verbs","pattern":"ich habe mich erkältet (perfect tense of reflexive)","explanation":"Sich erkälten uses the perfect tense with haben: Ich habe mich erkältet = I have caught a cold. The reflexive pronoun (mich) stays before the past participle (erkältet). Common illness phrases also use haben: Ich habe Fieber / Ich habe Husten.","examples":[{"sentence":"Sie hat sich erkältet.","translation":"She has caught a cold."},{"sentence":"Ich erhole mich langsam.","translation":"I am recovering slowly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Grippe'' means?","options":["flu","cold","cough","fever"],"correctAnswer":"flu"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have caught a cold.","options":["Ich habe mich erkältet.","Ich habe Fieber.","Ich niese.","Die Erkältung ist schlimm."],"correctAnswer":"Ich habe mich erkältet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ mich langsam.","options":["erhole","erkälte","niese","heile"],"correctAnswer":"erhole"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am staying home today","wordBankItems":["Ich","bleibe","heute","zu","Hause","."],"correctAnswer":"Ich bleibe heute zu Hause ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Krankmeldung'' means?","options":["sick note","prescription","appointment","insurance"],"correctAnswer":"sick note"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

